settings.custom_css:
/* FILTER BY SERVICE: which services show under each stage.
   Inside each :not( ) is that stage's list of tag slugs (Posts > Tags > Slug column).
   To ADD a service: add a line  [data-filter="new-tag-slug"],  to its stage (comma after every line but the last).
   To MOVE a service: move its line to another stage. */

/* firstbrand */
.fs-tfilter--brand .e-filter-item:not(
  [data-filter="branding-and-content"],
  [data-filter="website-design"],
  [data-filter="analytics"],
  [data-filter="crm"]
) { display: none !important; }

/* firstthought */
.fs-tfilter--thought .e-filter-item:not(
  [data-filter="seo-and-aeo"],
  [data-filter="advertising"],
  [data-filter="social-media"]
) { display: none !important; }

/* firstchoice */
.fs-tfilter--choice .e-filter-item:not(
  [data-filter="lead-generation"],
  [data-filter="marketing-automation"]
) { display: none !important; }

/* firstreferral */
.fs-tfilter--referral .e-filter-item:not(
  [data-filter="reviews-and-referrals"]
) { display: none !important; }
